package com.circuitsim.cli;

import com.circuitsim.engine.*;
import static com.circuitsim.engine.CircuitSimEngine.*;
import java.io.*;import java.nio.file.*;import java.util.*;

/** CLI adapter; formatting and file delivery stay outside the engine. */
public final class Main {
 private Main(){}
 public static void main(String[] args){int code=run(args);if(code!=0)System.exit(code);}
 static int run(String[] args){Path input=null,out=null;String format="text";Method method=null;
  for(int i=0;i<args.length;i++){switch(args[i]){case "--format"->{if(++i>=args.length)return usage("--format requires text|json|both");format=args[i].toLowerCase(Locale.ROOT);if(!Set.of("text","json","both").contains(format))return usage("Unsupported format: "+format);}case "--output"->{if(++i>=args.length)return usage("--output requires a CSV path");out=Path.of(args[i]);}case "--method"->{if(++i>=args.length)return usage("--method requires be|trap");method=switch(args[i].toLowerCase(Locale.ROOT)){case "be"->Method.BACKWARD_EULER;case "trap"->Method.TRAPEZOIDAL;default->null;};if(method==null)return usage("Unsupported method");}default->{if(args[i].startsWith("-"))return usage("Unknown option: "+args[i]);if(input!=null)return usage("Only one netlist file is supported");input=Path.of(args[i]);}}}
  if(input==null)return usage("Missing netlist file");try{NetlistParser.Parsed p=new NetlistParser().parse(input);AnalysisRequest req=p.request();if(method!=null&&req.kind()==AnalysisKind.TRANSIENT)req=new AnalysisRequest(req.kind(),req.step(),req.stop(),method);SimulationResult r=new CircuitSimEngine().simulate(p.circuit(),req);if(format.equals("text")||format.equals("both"))System.out.print(text(r));if(format.equals("json")||format.equals("both"))System.out.println(json(r));if(out!=null){if(req.kind()!=AnalysisKind.TRANSIENT) {System.err.println("CSV output requires .TRAN analysis");return 2;}writeCsv(out,r.samples());}return r.successful()?0:1;
  }catch(Exception e){System.err.println("CircuitSim error: "+e.getMessage());if(format.equals("json")||format.equals("both"))System.out.println("{\"status\":\"FAILED\",\"diagnostics\":[{\"code\":\"INPUT_OR_OUTPUT_ERROR\",\"message\":"+quote(e.getMessage())+"}]}");return 2;}}
 private static int usage(String s){System.err.println(s+"\nUsage: circuitsim [--format text|json|both] [--method be|trap] [--output results.csv] netlist.cir");return 2;}
 private static String text(SimulationResult r){StringBuilder b=new StringBuilder("CircuitSim analysis: ").append(r.analysis()).append("\nStatus: ").append(r.status()).append('\n');r.nodeVoltages().forEach((k,v)->b.append("V(").append(k).append(") = ").append(v).append(" V\n"));r.componentCurrents().forEach((k,v)->b.append("I(").append(k).append(") = ").append(v).append(" A\n"));if(!r.samples().isEmpty())b.append("Accepted samples: ").append(r.samples().size()).append('\n');for(Diagnostic d:r.diagnostics())b.append("[ ").append(d.code()).append(" ] ").append(d.message()).append('\n');return b.toString();}
 private static String json(SimulationResult r){StringBuilder b=new StringBuilder("{\"status\":").append(quote(r.status().name())).append(",\"analysis\":").append(quote(r.analysis().name())).append(",\"nodeVoltages\":").append(map(r.nodeVoltages())).append(",\"componentCurrents\":").append(map(r.componentCurrents())).append(",\"samples\":[");for(int i=0;i<r.samples().size();i++){if(i>0)b.append(',');Sample s=r.samples().get(i);b.append("{\"time\":").append(s.time()).append(",\"nodeVoltages\":").append(map(s.nodeVoltages())).append(",\"componentCurrents\":").append(map(s.componentCurrents())).append('}');}b.append("],\"diagnostics\":[");for(int i=0;i<r.diagnostics().size();i++){if(i>0)b.append(',');Diagnostic d=r.diagnostics().get(i);b.append("{\"code\":").append(quote(d.code())).append(",\"message\":").append(quote(d.message())).append(",\"stage\":").append(quote(d.stage())).append('}');}return b.append("],\"iterations\":").append(r.iterations()).append('}').toString();}
 private static String map(Map<String,Double> m){StringJoiner j=new StringJoiner(",","{","}");m.forEach((k,v)->j.add(quote(k)+":"+(Double.isFinite(v)?Double.toString(v):"null")));return j.toString();}
 private static String quote(String s){if(s==null)return "null";return "\""+s.replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n").replace("\r","\\r")+"\"";}
 private static void writeCsv(Path p,List<Sample> ss)throws IOException{TreeSet<String> nodes=new TreeSet<>(),currents=new TreeSet<>();for(Sample s:ss){nodes.addAll(s.nodeVoltages().keySet());currents.addAll(s.componentCurrents().keySet());}try(BufferedWriter w=Files.newBufferedWriter(p)){w.write("time_s");for(String n:nodes)w.write(",V_"+n+"_V");for(String c:currents)w.write(",I_"+c+"_A");w.newLine();for(Sample s:ss){w.write(Double.toString(s.time()));for(String n:nodes)w.write(s.nodeVoltages().containsKey(n)?","+s.nodeVoltages().get(n):",");for(String c:currents)w.write(s.componentCurrents().containsKey(c)?","+s.componentCurrents().get(c):",");w.newLine();}}}
}
